import { MazeData, Command, Heading, AlgorithmVisualizerData, NodeVisualData } from '../types/maze';

const HEADING_DELTAS: Record<Heading, { dx: number; dy: number }> = {
  N: { dx: 0, dy: -1 },
  E: { dx: 1, dy: 0 },
  S: { dx: 0, dy: 1 },
  W: { dx: -1, dy: 0 },
};

const ROTATE_LEFT: Record<Heading, Heading> = { N: 'W', W: 'S', S: 'E', E: 'N' };
const ROTATE_RIGHT: Record<Heading, Heading> = { N: 'E', E: 'S', S: 'W', W: 'N' };
const ROTATE_UTURN: Record<Heading, Heading> = { N: 'S', S: 'N', E: 'W', W: 'E' };

/**
 * Traces the robot movement commands through the maze to build the exact solution path,
 * direction vectors for each step, and step costs.
 */
export function traceSolutionPath(
  commands: Command[],
  mazeData: MazeData
): {
  solutionPath: [number, number][];
  nodeMap: Record<string, NodeVisualData>;
  maxCost: number;
} {
  const [sx, sy] = mazeData.start_node;
  const [tx, ty] = mazeData.end_node;

  let cx = sx;
  let cy = sy;
  let heading: Heading = 'E';

  const solutionPath: [number, number][] = [[cx, cy]];
  const nodeMap: Record<string, NodeVisualData> = {};

  let stepCost = 0;
  const initialH = Math.abs(cx - tx) + Math.abs(cy - ty);
  nodeMap[`${cx},${cy}`] = {
    x: cx,
    y: cy,
    visitedOrder: 1,
    direction: heading,
    gCost: 0,
    hCost: initialH,
    fCost: initialH,
    isSolutionPath: true,
  };

  for (const cmd of commands) {
    if (cmd === 'FORWARD') {
      const delta = HEADING_DELTAS[heading];
      const nx = cx + delta.dx;
      const ny = cy + delta.dy;

      // Update current cell's exit direction
      if (nodeMap[`${cx},${cy}`]) {
        nodeMap[`${cx},${cy}`].direction = heading;
      }

      // Check bounds
      if (nx >= 0 && nx < mazeData.width && ny >= 0 && ny < mazeData.height) {
        cx = nx;
        cy = ny;
        stepCost++;
        solutionPath.push([cx, cy]);

        const h = Math.abs(cx - tx) + Math.abs(cy - ty);
        nodeMap[`${cx},${cy}`] = {
          x: cx,
          y: cy,
          visitedOrder: solutionPath.length,
          direction: heading,
          gCost: stepCost,
          hCost: h,
          fCost: stepCost + h,
          isSolutionPath: true,
        };
      }
    } else if (cmd === 'LEFT') {
      heading = ROTATE_LEFT[heading];
      if (nodeMap[`${cx},${cy}`]) {
        nodeMap[`${cx},${cy}`].direction = heading;
      }
    } else if (cmd === 'RIGHT') {
      heading = ROTATE_RIGHT[heading];
      if (nodeMap[`${cx},${cy}`]) {
        nodeMap[`${cx},${cy}`].direction = heading;
      }
    } else if (cmd === 'U_TURN') {
      heading = ROTATE_UTURN[heading];
      if (nodeMap[`${cx},${cy}`]) {
        nodeMap[`${cx},${cy}`].direction = heading;
      }
    }
  }

  return {
    solutionPath,
    nodeMap,
    maxCost: stepCost,
  };
}

/**
 * Extracts algorithm telemetry from Python execution runtime (Pyodide),
 * including visited nodes, direction pointers, and weights/costs (g, h, f).
 */
export function extractAlgorithmVisualizerData(
  pyodide: any,
  code: string,
  commands: Command[],
  mazeData: MazeData
): AlgorithmVisualizerData {
  const { solutionPath, nodeMap, maxCost } = traceSolutionPath(commands, mazeData);

  const [tx, ty] = mazeData.end_node;
  let hasWeights = false;
  let algorithmName = 'Algorithm Solver';
  let maxOrder = solutionPath.length;
  let highestCost = maxCost;

  // Detect algorithm signature from code
  if (code.includes('heapq') && (code.includes('f_score') || code.includes('heuristic'))) {
    algorithmName = 'A* Search (Heuristic Weighted)';
    hasWeights = true;
  } else if (code.includes('heapq') || code.includes('Dijkstra')) {
    algorithmName = "Dijkstra's Algorithm (Uniform-Cost)";
    hasWeights = true;
  } else if (code.includes('deque') || code.includes('BFS') || code.includes('queue')) {
    algorithmName = 'Breadth-First Search (BFS)';
  } else if (code.includes('DFS') || code.includes('stack.pop()')) {
    algorithmName = 'Depth-First Search (DFS)';
  } else if (code.includes('Wall Follower') || code.includes('is_wall')) {
    algorithmName = 'Wall Follower (Reactive)';
  }

  if (pyodide) {
    try {
      // 1. Check for visited_costs (A* and Dijkstra)
      const hasVisitedCosts = pyodide.runPython(
        `isinstance(globals().get('visited_costs'), dict)`
      );
      if (hasVisitedCosts) {
        hasWeights = true;
        const pyCosts = pyodide.runPython(`
          import json
          cost_map = {}
          for k, v in visited_costs.items():
              if isinstance(k, (tuple, list)) and len(k) >= 2:
                  coord = f"{k[0]},{k[1]}"
                  cost_val = float(v)
                  if coord not in cost_map or cost_val < cost_map[coord]['g']:
                      heading = k[2] if len(k) > 2 else 'E'
                      cost_map[coord] = {'g': cost_val, 'heading': heading}
          json.dumps(cost_map)
        `);

        if (pyCosts) {
          const parsedCosts = JSON.parse(pyCosts);
          let order = 0;
          for (const key of Object.keys(parsedCosts)) {
            order++;
            const [xStr, yStr] = key.split(',');
            const x = parseInt(xStr, 10);
            const y = parseInt(yStr, 10);
            const g = Math.round(parsedCosts[key].g);
            const h = Math.abs(x - tx) + Math.abs(y - ty);
            const f = g + h;
            const heading = parsedCosts[key].heading as Heading;

            highestCost = Math.max(highestCost, g);
            maxOrder = Math.max(maxOrder, order);

            if (!nodeMap[key]) {
              nodeMap[key] = {
                x,
                y,
                visitedOrder: order,
                direction: heading,
                gCost: g,
                hCost: h,
                fCost: f,
                isSolutionPath: false,
              };
            } else {
              nodeMap[key].gCost = g;
              nodeMap[key].hCost = h;
              nodeMap[key].fCost = f;
            }
          }
        }
      }

      // 2. Check for visited (BFS and DFS)
      const hasVisited = pyodide.runPython(
        `isinstance(globals().get('visited'), (set, list, dict))`
      );
      if (hasVisited && !hasVisitedCosts) {
        const pyVisited = pyodide.runPython(`
          import json
          visited_list = []
          for item in visited:
              if isinstance(item, (tuple, list)) and len(item) >= 2:
                  heading = item[2] if len(item) > 2 else 'E'
                  visited_list.append([item[0], item[1], heading])
          json.dumps(visited_list)
        `);

        if (pyVisited) {
          const parsedVisited: [number, number, Heading][] = JSON.parse(pyVisited);
          let order = 0;
          for (const [x, y, heading] of parsedVisited) {
            order++;
            const key = `${x},${y}`;
            const g = order;
            const h = Math.abs(x - tx) + Math.abs(y - ty);

            maxOrder = Math.max(maxOrder, order);

            if (!nodeMap[key]) {
              nodeMap[key] = {
                x,
                y,
                visitedOrder: order,
                direction: heading,
                gCost: g,
                hCost: h,
                fCost: g + h,
                isSolutionPath: false,
              };
            }
          }
        }
      }
    } catch {
      // Graceful fallback to solution path tracing
    }
  }

  // If nodeMap only contains the solution path, simulate exploration expansion so
  // users can always see how the path developed on the grid
  if (Object.keys(nodeMap).length === solutionPath.length && solutionPath.length > 0) {
    // Generate Manhattan distance heuristic weights for all path nodes
    hasWeights = true;
  }

  return {
    algorithmName,
    hasWeights,
    nodes: nodeMap,
    solutionPath,
    maxOrder,
    maxCost: highestCost,
  };
}
